const $=s=>document.querySelector(s);const params=new URLSearchParams(location.search);let corrected=params.get('state')==='corrected';let selected=null;
function save(){const q=new URLSearchParams();if(corrected)q.set('state','corrected');if(selected)q.set('object',selected);if($('#restore').checked)q.set('restore','yes');history.replaceState(null,'',location.pathname+(q.size?'?'+q:'')+location.hash)}
function state(){document.querySelectorAll('[data-state]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.state==='corrected')===corrected)));document.querySelectorAll('.vowel').forEach(x=>x.textContent=corrected?'ο':'ω');document.querySelectorAll('.gloss').forEach(x=>x.textContent=corrected?'We have peace.':'Let us have peace.');$('#sin-label').textContent=corrected?'א¹':'א*';$('#vat-label').textContent=corrected?'B²':'B*';$('#finding-title').textContent=corrected?'Two objects. Later textual states.':'Two first hands favor an exhortation.';$('#finding-copy').textContent=corrected?'The corrections now agree with the edition. They are not two extra manuscripts, and agreement does not prove the corrections right.':'The edition prints an assertion. The editor’s line is a decision, not a third ancient object.';save()}
function evidence(id){selected=id;document.querySelectorAll('[data-object]').forEach(b=>{b.setAttribute('aria-expanded',String(b.dataset.object===id));b.querySelector('.arrow').textContent=b.dataset.object===id?'×':'⌄'});$('#evidence').hidden=!id;if(id){$('#evidence-title').textContent=id==='sin'?'Sinaiticus · BL folio 262b':'Vaticanus · reported correction B²';$('#evidence-copy').textContent=id==='sin'?'NET’s note reports omega in the first hand and omicron in the correction labeled א¹. The object viewer locates the passage on BL folio 262b. These are two recorded states of one codex. No fresh letter-level collation or date for the correction is claimed.':'NET’s note reports omega in B* and omicron in B². This report follows that apparatus’s labels. It does not establish that Vaticanus and Sinaiticus were corrected together or at the same date.';$('#object-source').href=id==='sin'?'https://codexsinaiticus.org/en/manuscript.aspx?book=37&chapter=5&lid=en&side=r&zoomSlider=0':'https://bible.org/download/netbible/ondemand/bybook/rom.pdf#page=9'}save()}
document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{corrected=b.dataset.state==='corrected';state()});document.querySelectorAll('[data-object]').forEach(b=>b.onclick=()=>evidence(selected===b.dataset.object?null:b.dataset.object));function close(){const b=document.querySelector('[data-object="'+selected+'"]');evidence(null);b?.focus({preventScroll:true});if(b&&b.getBoundingClientRect().top<72)b.scrollIntoView({block:'center',behavior:'instant'})}$('#close').onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&selected)close()});function restore(){const on=$('#restore').checked;$('#supplied').textContent=on?'[ημα]':'[ … ]';$('#restore-status').textContent=on?'θέλημα · “will”. The supplied letters complete the word; they remain a reconstruction, not surviving ink.':'A gap remains. This is loss of material, not a shorter reading.';save()}$('#restore').onchange=restore;$('#restore').checked=params.get('restore')==='yes';state();if(['sin','vat'].includes(params.get('object')))evidence(params.get('object'));restore();
const endingData={
 sinaiticus:{tag:'Sinaiticus · BL folio 228',title:'A conclusion survives here.',observation:'Mark concludes at 16:8 with its end-title; Luke follows on the surviving page. The Longer Ending is absent from this preserved conclusion.',inference:'This is evidence for a text ending at 16:8. Whether an earlier ending was lost before this copy is a different question.',url:'https://codexsinaiticus.org/en/manuscript.aspx?book=34&chapter=16&verse=8&lid=en&side=r&zoomSlider=0',diagram:'<rect x="57" y="44" width="130" height="38" fill="#b5d3bf"/><text x="68" y="68" font-size="14">Mark 16:8</text><path d="M57 94H187" stroke="#246861" stroke-width="4"/><text x="68" y="116" font-size="11">End-title</text><text x="68" y="160" font-size="16">Luke begins</text>'},
 alexandrinus:{tag:'Alexandrinus · selected coverage report',title:'The text continues.',observation:'Alexandrinus contains Mark 16:9–20. This lane reports presence of the Longer Ending; it is not a word-by-word transcription.',inference:'It witnesses the continuation in this codex. That fact alone does not establish who composed the ending. The report follows the cited scholarship; no fresh image collation is claimed.',url:'https://textandcanon.org/a-case-against-the-longer-ending-of-mark/',diagram:'<rect x="57" y="44" width="130" height="123" fill="#b5d3bf"/><text x="68" y="68" font-size="14">Mark 16:8</text><path d="M57 90H187" stroke="#246861" stroke-dasharray="3 4"/><text x="68" y="118" font-size="14">16:9–20</text><text x="68" y="146" font-size="11">Continuation</text>'},
 p45:{tag:'P45 · CSNTM folio inventory',title:'There is no reading to compare.',observation:'The surviving inventory includes portions of Mark 4–9 and 11–12, but no Mark 16. The relevant material is not extant.',inference:'P45 supports neither ending at this location. Its earlier date does not let it answer a question for which its text does not survive.',url:'https://images.csntm.org/Manuscripts/GA_P45/P45_(Dublin_CBL_BP_I).pdf',diagram:'<rect x="57" y="44" width="130" height="123" fill="none" stroke="#8e9e92" stroke-width="2" stroke-dasharray="5 5"/><text x="68" y="94" font-size="14">Mark 16</text><text x="68" y="121" font-size="14">not extant</text>'}
};
function chooseEnding(id){const d=endingData[id];document.querySelectorAll('[data-ending]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.ending===id)));document.getElementById('ending-tag').textContent=d.tag;document.getElementById('ending-title').textContent=d.title;document.getElementById('ending-observation').textContent=d.observation;document.getElementById('ending-inference').textContent=d.inference;document.getElementById('ending-source').href=d.url;document.getElementById('ending-diagram').innerHTML=d.diagram;document.getElementById('object-diagram-title').textContent='Schematic reading sequence: '+d.title;sessionStorage.setItem('passage-prototype-ending',id)}
document.querySelectorAll('[data-ending]').forEach(b=>b.addEventListener('click',()=>chooseEnding(b.dataset.ending)));chooseEnding(endingData[sessionStorage.getItem('passage-prototype-ending')]?sessionStorage.getItem('passage-prototype-ending'):'sinaiticus');
